const MAX_N:usize=10;const MAX_SOLUTIONS:usize=1024;const MAX_OUTPUT:usize=90120;
fn visit(nums:&[i64],target:i64,start:usize,current:i64,remaining:i64,path:&mut [i64;MAX_N],depth:usize,out:&mut [[i64;MAX_N];MAX_SOLUTIONS],lens:&mut [usize;MAX_SOLUTIONS],count:&mut usize){if current>target||remaining+current<target{return;}if current==target{let k=*count;lens[k]=depth;out[k][..depth].copy_from_slice(&path[..depth]);*count+=1;return;}for i in start..nums.len(){path[depth]=nums[i];visit(nums,target,i+1,current+nums[i],remaining-nums[i],path,depth+1,out,lens,count);}}
fn put64(out:&mut[u8],pos:&mut usize,x:i64){out[*pos..*pos+8].copy_from_slice(&x.to_le_bytes());*pos+=8;}
#[no_mangle]pub unsafe extern "C" fn sum_of_subsets(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<2{return -1;}let nn=*input;let target=*input.add(1);if nn<0||nn>10||length!=nn as usize+2||target<0||target>250{return -1;}let n=nn as usize;let nums=std::slice::from_raw_parts(input.add(2),n);if nums.iter().any(|&x|x<0||x>50){return -1;}let mut out=[[0i64;MAX_N];MAX_SOLUTIONS];let mut lens=[0usize;MAX_SOLUTIONS];let mut count=0usize;let mut path=[0i64;MAX_N];visit(nums,target,0,0,nums.iter().sum(),&mut path,0,&mut out,&mut lens,&mut count);let need=8+(0..count).map(|i|8+8*lens[i]).sum::<usize>();if output.is_null()||capacity<need{return -2;}let bytes=std::slice::from_raw_parts_mut(output,need);let mut pos=0;put64(bytes,&mut pos,count as i64);for i in 0..count{put64(bytes,&mut pos,lens[i] as i64);for j in 0..lens[i]{put64(bytes,&mut pos,out[i][j]);}}pos as i64}
